using System.Globalization;
using System.Text.Json;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Routing;
using Microsoft.Extensions.Configuration;
using Microsoft.Extensions.Hosting;

namespace PoMiniGames.Features.PoGallery;

/// <summary>
/// PoGallery — dev-only demo surface for procedural Three.js models generated by
/// the img2threejs skill. See <see cref="PoGalleryEndpoints"/> for the manifest
/// endpoint and gating rationale.
///
/// Wire format:
///   GET  /api/diag/gallery → <see cref="GalleryManifest"/> (200) or 404 when disabled.
///   POST /api/gallery/upload → accept an image, store it, and return the refreshed
///        <see cref="GalleryManifest"/> (200) or 404 when disabled.
///
/// Pre-authored models are static ES modules under <c>wwwroot/games/pogallery/models/&lt;id&gt;/index.js</c>.
/// Uploaded images are stored under <c>wwwroot/games/pogallery/uploads/&lt;id&gt;/</c> and rendered
/// client-side by the viewer as an image-driven heightfield (see the viewer's
/// <c>?image=</c> mode). The Blazor page renders each model in an iframe pointing at
/// <c>/games/pogallery/viewer/?model=…&amp;title=…</c> or <c>/games/pogallery/viewer/?image=…&amp;title=…</c>.
/// </summary>
public static class PoGalleryEndpoints
{
    /// <summary>Max accepted upload size (5 MB) — generous for a reference photo, small
    /// enough to keep the static-file serving and the client-side heightfield sampling fast.</summary>
    internal const long MaxUploadBytes = 5 * 1024 * 1024;

    private static readonly string[] AllowedImageTypes = { "image/png", "image/jpeg", "image/webp" };

    /// <summary>
    /// Single source of truth for the static catalogue. <c>Kind</c> discriminates:
    ///   - <c>"model"</c>: a procedural Three.js module under
    ///     <c>wwwroot/games/pogallery/models/&lt;id&gt;/index.js</c>. The page renders it
    ///     as a viewer iframe via <see cref="GalleryModel.ViewerUrl"/>.
    ///   - <c>"preset"</c>: a reference image under
    ///     <c>wwwroot/games/pogallery/refs/&lt;id&gt;.&lt;ext&gt;</c>. The page renders
    ///     a small thumbnail + a click handler that submits the image through
    ///     <c>/api/gallery/upload</c> for instant heightfield feedback. The
    ///     <see cref="GalleryModel.ViewerUrl"/> still points at the existing viewer
    ///     so the static manifest is browsable.
    /// When a new procedural model is generated, add a <c>"model"</c> entry here and
    /// drop the module under <c>wwwroot/games/pogallery/models/&lt;id&gt;/index.js</c>.
    /// When a new reference image is curated, add a <c>"preset"</c> entry and drop the
    /// file under <c>wwwroot/games/pogallery/refs/&lt;id&gt;.&lt;ext&gt;</c>.
    /// </summary>
    internal static readonly IReadOnlyList<GalleryModel> Models = new[]
    {
